"""Generate the C headers that the Nano sketch includes.

AI-assisted: drafted with Claude, checked by the author.
The test set is stored twice: the original pixels (0 to 16) and the exact
int8 inputs the PC used, so the board gets bit-identical inputs.
"""
from pathlib import Path

import numpy as np

from litert_quant.data import fingerprint, load_split
from litert_quant.model1 import input_quantization

ROOT = Path(__file__).resolve().parents[2]
MODEL_FILES = {"float": "digits_cnn_float.tflite", "int8": "digits_cnn_int8.tflite"}
HEADER = (
    "// Generated by scripts/make_firmware_data.py. Do not edit.\n"
    "// AI-assisted: drafted with Claude, checked by the author.\n"
)


def c_array(ctype, name, values, per_line=16, align=None):
    """Return C source for a const array and its length."""
    values = list(values)
    lines = []
    for i in range(0, len(values), per_line):
        chunk = values[i : i + per_line]
        lines.append("  " + ", ".join(str(int(v)) for v in chunk) + ",")
    prefix = "alignas(%d) " % align if align else ""
    body = "\n".join(lines)
    return "%sconst %s %s[] = {\n%s\n};\nconst unsigned int %s_len = %d;\n" % (
        prefix,
        ctype,
        name,
        body,
        name,
        len(values),
    )


def quantise_input(x, scale, zero):
    """The same int8 quantisation the PC evaluator applies to each sample."""
    q = np.clip(np.round(x / scale) + zero, -128, 127)
    return q.astype(np.int8)


def make_headers(models_dir, out_dir):
    models_dir = Path(models_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    _, x_test, _, y_test = load_split()
    n = len(x_test)
    flat = x_test.reshape(n, 64)
    pixels = np.rint(flat * 16).astype(np.uint8)
    assert np.array_equal(pixels.astype(np.float32) / 16.0, flat)
    int8_blob = (models_dir / MODEL_FILES["int8"]).read_bytes()
    scale, zero = input_quantization(int8_blob)
    q = quantise_input(x_test, scale, zero).reshape(n, 64)

    files = {}
    for kind, fname in MODEL_FILES.items():
        blob = (models_dir / fname).read_bytes()
        files["model_%s.h" % kind] = (
            HEADER
            + "#pragma once\n#include <stdint.h>\n\n"
            + c_array("unsigned char", "g_model_%s" % kind, blob, align=16)
        )
    text = HEADER + "#pragma once\n#include <stdint.h>\n\n"
    text += "// SHA-256 of the float test inputs and labels: %s\n" % fingerprint(
        x_test, y_test
    )
    text += "#define TEST_COUNT %d\n#define TEST_SIZE 64\n" % n
    text += "#define INPUT_ZERO_POINT %d\n\n" % zero
    text += c_array("uint8_t", "test_pixels", pixels.flatten().tolist(), per_line=32)
    text += "\n"
    text += c_array("int8_t", "test_input_int8", q.flatten().tolist(), per_line=32)
    text += "\n"
    text += c_array("uint8_t", "test_labels", y_test.astype(np.uint8).tolist(), per_line=32)
    files["test_data.h"] = text

    for name, body in files.items():
        (out_dir / name).write_text(body)
    return sorted(files)
